// Bông hoa 5 cánh: kind 'mai' (vàng) | 'dao' (hồng). k = độ nở 0..1.
const MAI = ['#fff0a0', '#ffd23f', '#f2a900', '#c9561a'], DAO = ['#fff1f5', '#ffb3c8', '#e2557f', '#9d2350'];
const flower = (c, x, y, R, rot, kind, k) => {
